      (lon - u_sdfBoundsMin.x) / (u_sdfBoundsMax.x - u_sdfBoundsMin.x),
      (u_sdfBoundsMax.y - lat) / (u_sdfBoundsMax.y - u_sdfBoundsMin.y)
